float thickness = 0.05;
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    vec2 uv = fragCoord/iResolution.y;



    uv = uv * 10.;


    vec3 col = vec3(1.,1.,1.);


    if(sin(uv.x *(sin(iTime))*4.) + 5. < uv.y + thickness && sin(uv.x *(sin(iTime))*4.) + 5. > uv.y - thickness )
    {
        col = vec3(0,0,0);
    }
    else if(cos(uv.x *(cos(iTime))) + 2. < uv.y + thickness*2. && cos(uv.x *(cos(iTime))) + 2. > uv.y - thickness*2. )
    {
        col = vec3(0.3,0.3,0.3);
    }
    else if(sin(uv.x *(cos(iTime))) + 8. < uv.y + thickness*2. && sin(uv.x *(cos(iTime))) + 8. > uv.y - thickness*2. )
    {
        col = vec3(0.3,0.3,0.3);
    }


    // Output to screen
    fragColor = vec4(col,1.0);
}
